Future<DriveFileState> _pullRemoteDelete(
  DrivePath path,
  DriveFileState current,
  RemoteDriveItem remote,
) async {
  (await env.remove(path.absolute, force: true)).getOrThrow();
  return current.copyWith(
    remoteRevision: remote.revision,
