/// Provider whose page 1 holds the CHILD (live fork) and page 2 the PARENT
/// (live) — the exact ordering Thread 14 reports.
final class _ChildFirstProvider implements RemoteSessionProvider {
  @override
  String get providerId => 'probe';

  final _records = <String, CloudSessionRemoteRecord>{};
  final _bytes = <String, Uint8List>{};
  final listCursors = <String?>[];

  _ChildFirstProvider() {
    _bytes['child'] = _doc('child');
    _bytes['parent'] = _doc('parent');
    _records['child'] = CloudSessionRemoteRecord(
      sessionId: 'child',
      parentSessionId: 'parent',
      revision: 'r1',
      sha256: cryptoSha256(_bytes['child']!),
      size: _bytes['child']!.length,
    );
    _records['parent'] = CloudSessionRemoteRecord(
      sessionId: 'parent',
      parentSessionId: null,
      revision: 'r1',
      sha256: cryptoSha256(_bytes['parent']!),
      size: _bytes['parent']!.length,
    );
  }

  @override
  Future<DriveResult<CloudSessionPage>> list(
    CloudSessionScope scope,
    String? cursor,
  ) async {
    listCursors.add(cursor);
    final all = _records.values.toList();
    if (cursor == null) {
      return DriveResult.ok(
        CloudSessionPage(
          records: [all.firstWhere((r) => r.sessionId == 'child')],
          nextCursor: '1',
          hasMore: true,
        ),
      );
    }
    return DriveResult.ok(
      CloudSessionPage(
        records: [all.firstWhere((r) => r.sessionId == 'parent')],
      ),
    );
  }

  @override
  Future<DriveResult<CloudSessionDownload>> download(
    CloudSessionScope scope,
    String sessionId,
  ) async {
    final bytes = _bytes[sessionId]!;
    return DriveResult.ok(
      CloudSessionDownload(
        record: _records[sessionId]!,
        bytes: bytes,
      ),
    );
  }

  @override
  Future<DriveResult<CloudSessionRemoteRecord>> upload(
    CloudSessionUpload upload,
  ) async => throw UnimplementedError();

  @override
  Future<DriveResult<CloudSessionRemoteRecord>> delete(
    CloudSessionScope scope,
    String sessionId,
    String operationId,
    String? baseRevision,
    int authGeneration,
  ) async => throw UnimplementedError();
}

